using System.Collections.Generic;
using UnityEngine;
using HarborValeGreybox.Driving;
namespace HarborValeGreybox.Racing {
// Inputs only: tire forces, gear shifts and braking remain FinchVehicle's responsibility.
[DisallowMultipleComponent]
public sealed class HighwayDriver : MonoBehaviour {
 public static readonly List<HighwayDriver> Active=new List<HighwayDriver>();
 public FinchVehicle Car; public Vector3[] Path; public RoadPilot Proxy; public TrafficPersona Persona;
 public bool Held,IsRacer,IsPolice; public float CruiseKph=112.65408f; public int Index,Lane=1;
 public float LaneOffset {get;private set;} public int SignalDirection {get;private set;}
 public float DistanceMoved {get;private set;} public float TargetKph {get;private set;}
 public bool NeedsAssistedReset=>tippedFor>5||stalledFor>24||recoveryAttempts>=3;
 public int TargetLane=>pendingLane;
 readonly Collider[] overlaps=new Collider[96]; readonly FinchVehicle[] neighbors=new FinchVehicle[80]; readonly RaycastHit[] rearHits=new RaycastHit[16];
 readonly float[] neighborAlong=new float[80],neighborLateral=new float[80],neighborVelocity=new float[80];
 int neighborCount,pendingLane=1,recoveryAttempts; float[] arc; Vector3[] cachedPath; float length,progress,senseClock,decisionClock,signalAge,changeAge,stalledFor,tippedFor,impactAge=100,reverseClock; bool changing; Vector3 previous; bool havePrevious;
 const int SenseMask=~((1<<28)|(1<<29)|(1<<31)); const float LaneWidth=3.6f;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]static void Clear(){Active.Clear();}
 void OnEnable(){if(!Active.Contains(this))Active.Add(this);}
 void OnDisable(){Active.Remove(this);if(Car!=null){Car.commandedPedal=0;Car.commandedServiceBrake=1;}}
 void Start(){if(Car==null)Car=GetComponent<FinchVehicle>();if(Persona==null)Persona=GetComponent<TrafficPersona>();if(Persona!=null&&!Persona.Configured)Persona.Configure(Persona.Seed);Lane=Mathf.Clamp(Lane,0,2);pendingLane=Lane;LaneOffset=Offset(Lane);SetProxy(Proxy);}
 void FixedUpdate(){Drive(Time.fixedDeltaTime);}
 public void SetProxy(RoadPilot proxy){Proxy=proxy;if(proxy==null)return;proxy.enabled=false;proxy.Car=Car;proxy.Path=Path;proxy.Index=Index;proxy.IsRival=IsRacer;}
 static float Offset(int lane)=>(1-Mathf.Clamp(lane,0,2))*LaneWidth;
 int Wrap(int i)=>(i%Path.Length+Path.Length)%Path.Length;
 bool Ready(){if(Car==null||Path==null||Path.Length<8)return false;if(cachedPath!=Path){cachedPath=Path;arc=new float[Path.Length+1];for(int i=0;i<Path.Length;i++)arc[i+1]=arc[i]+Vector3.Distance(Path[i],Path[(i+1)%Path.Length]);length=arc[Path.Length];}return length>1;}
 Vector3 Forward(int i){Vector3 f=Path[Wrap(i+1)]-Path[Wrap(i-1)];return f.sqrMagnitude>.001f?f.normalized:Vector3.forward;}
 Vector3 Right(int i){return Vector3.Cross(Vector3.up,Forward(i)).normalized;}
 public Vector3 Point(int i){return Path[Wrap(i)]+Right(i)*LaneOffset;}
 public void Place(int index,int lane){if(!Ready())return;Index=Wrap(index);Lane=pendingLane=Mathf.Clamp(lane,0,2);LaneOffset=Offset(Lane);changing=false;SignalDirection=0;signalAge=0;Car.ResetAt(Point(Index)+Vector3.up*.35f,Quaternion.LookRotation(Forward(Index),Vector3.up));previous=Car.transform.position;havePrevious=true;stalledFor=tippedFor=reverseClock=0;recoveryAttempts=0;impactAge=100;Project(Car.transform.position,Index,out progress,out _,out Index);if(Proxy!=null)Proxy.Index=Index;}
 // Projects locally onto the curved carriageway; signed arc distance also works at the loop seam.
 void Project(Vector3 position,int near,out float s,out float lateral,out int index){float best=float.MaxValue;s=0;lateral=0;index=Wrap(near);for(int n=-45;n<=45;n++){int i=Wrap(near+n),j=Wrap(i+1);Vector3 edge=Path[j]-Path[i];float t=Mathf.Clamp01(Vector3.Dot(position-Path[i],edge)/Mathf.Max(.001f,edge.sqrMagnitude));Vector3 p=Path[i]+edge*t;float d=(position-p).sqrMagnitude;if(d<best){best=d;index=i;s=arc[i]+edge.magnitude*t;lateral=Vector3.Dot(position-p,Right(i));}}}
 float SignedDistance(float s){float d=s-progress;if(d>length*.5f)d-=length;if(d< -length*.5f)d+=length;return d;}
 void Sense(){neighborCount=0;sensorFull=false;for(int i=0;i<Active.Count;i++){var a=Active[i];if(a==null||a==this||a.Car==null||a.Path!=Path)continue;if((a.Car.transform.position-Car.transform.position).sqrMagnitude<210*210)AddNeighbor(a.Car);}int count=Physics.OverlapSphereNonAlloc(Car.transform.position,150,overlaps,SenseMask,QueryTriggerInteraction.Ignore);for(int i=0;i<count;i++){var other=overlaps[i].GetComponentInParent<FinchVehicle>();if(other!=null&&other!=Car)AddNeighbor(other);}sensorFull|=count==overlaps.Length;for(int i=0;i<neighborCount;i++)Relative(neighbors[i],out neighborAlong[i],out neighborLateral[i],out neighborVelocity[i]);}
 bool sensorFull;
 void AddNeighbor(FinchVehicle v){for(int i=0;i<neighborCount;i++)if(neighbors[i]==v)return;if(neighborCount<neighbors.Length)neighbors[neighborCount++]=v;else sensorFull=true;}
 bool InLane(FinchVehicle other,int lane,float lateral){var d=other.GetComponent<HighwayDriver>();if(d!=null&&d.Path==Path&&d.SignalDirection!=0&&d.TargetLane==lane)return true;return Mathf.Abs(lateral-Offset(lane))<2.15f;}
 void Relative(FinchVehicle other,out float along,out float lateral,out float velocity){Project(other.transform.position,Index,out float s,out lateral,out int i);along=SignedDistance(s);velocity=other.Body==null?0:Vector3.Dot(other.Body.linearVelocity,Forward(i));if(Mathf.Abs(other.transform.position.y-Path[i].y)>5)along=length;}
 float Follow(int lane,float desired,out bool blocked){float result=desired,speed=Car.SpeedKph/3.6f;blocked=false;float headway=IsRacer?1.25f:Persona==null?1.8f:Persona.HeadwaySeconds;for(int i=0;i<neighborCount;i++){var other=neighbors[i];if(other==null)continue;float along=neighborAlong[i],lat=neighborLateral[i],v=neighborVelocity[i];if(along<0||along>150||!InLane(other,lane,lat))continue;float gap=along-4.8f;float needed=4+speed*headway+Mathf.Max(0,(speed*speed-v*v)/(2*5));if(gap<needed+15)blocked=true;float follow=Mathf.Max(0,v+(gap-4-speed*headway)*.55f)*3.6f;float stopping=Mathf.Sqrt(Mathf.Max(0,v)*Mathf.Max(0,v)+2*4.5f*Mathf.Max(0,gap-4-speed*.8f))*3.6f;follow=Mathf.Min(follow,stopping);if(gap<3)follow=0;result=Mathf.Min(result,follow);}return result;}
 bool LaneClear(int lane){if(lane<0||lane>2||sensorFull)return false;float speed=Car.SpeedKph/3.6f;for(int i=0;i<neighborCount;i++){var other=neighbors[i];if(other==null)continue;float along=neighborAlong[i],lat=neighborLateral[i],v=neighborVelocity[i];if(!InLane(other,lane,lat))continue;float gap=Mathf.Abs(along)-5;float closing=along<0?v-speed:speed-v;float minimum=along<0?Mathf.Max(15,v*1.1f):Mathf.Max(18,speed*1.35f);if(gap<minimum||closing>0&&gap/closing<5)return false;}return true;}
 float Desired(int lane){if(IsRacer||IsPolice)return CruiseKph;if(Persona!=null)return Persona.DesiredHighwayKph(lane);return (lane==0?59:lane==1?68:75)*1.609344f;}
 void Request(int lane){if(!LaneClear(lane))return;pendingLane=lane;SignalDirection=lane>Lane?-1:1;signalAge=changeAge=0;changing=false;}
 void LanePlan(float dt){decisionClock-=dt;if(SignalDirection!=0){signalAge+=dt;if(!changing){if(!LaneClear(pendingLane)){pendingLane=Lane;SignalDirection=0;decisionClock=1;return;}if(signalAge>=.8f)changing=true;}if(changing){changeAge+=dt;LaneOffset=Mathf.MoveTowards(LaneOffset,Offset(pendingLane),dt*(IsRacer?1.45f:1.05f));if(Mathf.Abs(LaneOffset-Offset(pendingLane))<.015f){Lane=pendingLane;SignalDirection=0;changing=false;decisionClock=2.5f;}}return;}if(decisionClock>0)return;decisionClock=.6f;Follow(Lane,Desired(Lane),out bool blocked);bool camper=Persona!=null&&Persona.IsCamper&&!IsRacer&&!IsPolice;int preferred=Persona==null?1:Persona.PreferredLane;if(blocked&&Lane<2&&LaneClear(Lane+1)){Request(Lane+1);return;}if(blocked&&(IsRacer||IsPolice)&&Lane>0&&LaneClear(Lane-1)){Request(Lane-1);return;}if(camper&&Lane<2&&LaneClear(Lane+1)){Request(Lane+1);return;}if(!camper&&Lane==2&&LaneClear(1)){Request(1);return;}if(!blocked&&Lane>preferred&&LaneClear(Lane-1)){Request(Lane-1);return;}if(!blocked&&Lane<preferred&&LaneClear(Lane+1))Request(Lane+1);}
 float CornerSpeed(float desired){float target=desired,travel=0,speed=Car.SpeedKph/3.6f,horizon=Mathf.Clamp(speed*speed/6+25,70,240);int i=Index;for(int n=0;n<Path.Length-6&&travel<horizon;n+=2){Vector3 a=Path[Wrap(i)],b=Path[Wrap(i+3)],c=Path[Wrap(i+6)];Vector3 ab=b-a,bc=c-b;ab.y=bc.y=0;float angle=Vector3.Angle(ab,bc)*Mathf.Deg2Rad;if(angle>.001f){float radius=(ab.magnitude+bc.magnitude)*.5f/angle;float curveSpeed=Mathf.Sqrt(Mathf.Max(3,radius-Mathf.Abs(LaneOffset))*3.3f);target=Mathf.Min(target,Mathf.Sqrt(curveSpeed*curveSpeed+2*3.5f*Mathf.Max(0,travel-8))*3.6f);}travel+=Vector3.Distance(Path[Wrap(i)],Path[Wrap(i+2)]);i+=2;}return target;}
 public void Drive(float dt){if(!Ready()||dt<=0)return;Car.externalInput=true;Car.commandedHandbrake=false;Car.commandedPedal=0;Car.commandedServiceBrake=0;if(Proxy!=null){Proxy.enabled=false;Proxy.Index=Index;}bool held=Held||Proxy!=null&&Proxy.Held;if(held){Car.commandedServiceBrake=1;Car.commandedSteer=0;previous=Car.transform.position;havePrevious=true;return;}Vector3 pos=Car.transform.position;if(havePrevious)DistanceMoved+=Vector3.Distance(previous,pos);previous=pos;havePrevious=true;Project(pos,Index,out progress,out float lateral,out Index);if(Proxy!=null)Proxy.Index=Index;senseClock-=dt;if(senseClock<=0){Sense();senseClock=.14f;}impactAge+=dt;LanePlan(dt);
  float look=Mathf.Clamp(7+Car.SpeedKph*.18f,7,32),travel=0;int goal=Index;while(travel<look&&travel<length*.5f){travel+=Vector3.Distance(Path[goal],Path[Wrap(goal+1)]);goal=Wrap(goal+1);}Vector3 local=Car.transform.InverseTransformPoint(Point(goal));float angle=Mathf.Atan2(local.x,local.z),steerAngle=Mathf.Atan2(2*Car.wheelBase*Mathf.Sin(angle),Mathf.Max(4,local.magnitude))*Mathf.Rad2Deg;Car.commandedSteer=Mathf.Clamp(steerAngle/Mathf.Lerp(Car.lowSpeedSteer,Car.highSpeedSteer,Mathf.Clamp01(Car.SpeedKph/130)),-1,1);
  float target=CornerSpeed(Desired(Lane));target=Follow(Lane,target,out _);if(SignalDirection!=0)target=Follow(pendingLane,target,out _);if(local.z<0||Mathf.Abs(lateral-LaneOffset)>5)target=Mathf.Min(target,18);TargetKph=target;float error=target-Car.SpeedKph;if(error< -1){Car.commandedServiceBrake=Mathf.Clamp01(-error/12);}else Car.commandedPedal=target<1?0:Mathf.Clamp01(error/13);
  bool tipped=Vector3.Dot(Car.transform.up,Vector3.up)<.4f;tippedFor=tipped?tippedFor+dt:0;stalledFor=Car.SpeedKph<3&&target>12?stalledFor+dt:Mathf.Max(0,stalledFor-dt*2);
  if(impactAge<20&&Car.SpeedKph<6&&!tipped&&recoveryAttempts<3&&stalledFor>1){reverseClock+=dt;bool reverse=reverseClock<1.7f;bool clear=RearClear();Car.commandedPedal=reverse&&clear?-.25f:reverse?0:.35f;Car.commandedServiceBrake=reverse&&!clear?1:0;Car.commandedSteer=reverse?-Mathf.Sign(local.x)*.6f:Car.commandedSteer;if(reverseClock>3.5f){recoveryAttempts++;reverseClock=0;}}else if(Car.SpeedKph>12){reverseClock=0;recoveryAttempts=0;}
  if(tipped||NeedsAssistedReset){Car.commandedPedal=0;Car.commandedServiceBrake=1;}
 }
 bool RearClear(){int count=Physics.SphereCastNonAlloc(Car.transform.position+Vector3.up*.7f-Car.transform.forward*2.7f,.8f,-Car.transform.forward,rearHits,7,SenseMask,QueryTriggerInteraction.Ignore);if(count==rearHits.Length)return false;for(int i=0;i<count;i++)if(!rearHits[i].collider.transform.IsChildOf(Car.transform)&&rearHits[i].normal.y<.7f)return false;return true;}
 void OnCollisionEnter(Collision c){if(c.relativeVelocity.magnitude>2.5f){impactAge=0;reverseClock=0;}}
}
}
